 import mongoose from "mongoose";

import {
  AIReportModel,
} from "../models/AIReport.model";

export interface ReportHistoryItem {
  _id: string;

  reportType: string;

  title: string;

  summary: string;

  createdAt: Date;

  updatedAt: Date;
}

export interface ReportHistoryResult {
  reports: ReportHistoryItem[];

  total: number;
}

/**
 * =========================================================
 * Get Report History
 * =========================================================
 *
 * Returns all AI reports generated by the logged-in user.
 *
 * Reports are sorted newest first.
 */
export async function getReportHistory(
  userId: string
): Promise<ReportHistoryResult> {
  /**
   * Validate MongoDB user ID
   */
  if (
    !mongoose.Types.ObjectId.isValid(
      userId
    )
  ) {
    throw new Error(
      "Invalid user ID."
    );
  }

  const userObjectId =
    new mongoose.Types.ObjectId(
      userId
    );

  /**
   * Fetch reports belonging
   * only to this user
   */
  const reports =
    await AIReportModel.find({
      user: userObjectId,
    })
      .select({
        _id: 1,
        reportType: 1,
        title: 1,
        summary: 1,
        createdAt: 1,
        updatedAt: 1,
      })
      .sort({
        createdAt: -1,
      })
      .lean();

  /**
   * Format response
   */
  const formattedReports: ReportHistoryItem[] =
    reports.map(
      (report: any) => ({
        _id: String(
          report._id
        ),

        reportType:
          report.reportType ||
          "unknown",

        title:
          report.title ||
          "AI Report",

        summary:
          report.summary ||
          "",

        createdAt:
          report.createdAt,

        updatedAt:
          report.updatedAt,
      })
    );

  return {
    reports:
      formattedReports,

    total:
      formattedReports.length,
  };
}